<?php
require_once __DIR__.'/_auth.php'; require_once __DIR__.'/../../../config/database.php';
$acoes=$conn->query("SELECT aa.*,a.nome_adm,u.nome_user,e.nome_evento,l.nome_local FROM Acao_Administrativa aa INNER JOIN Administrador a ON a.id_adm=aa.id_adm LEFT JOIN Usuario u ON u.id_user=aa.id_user LEFT JOIN Evento e ON e.id_evento=aa.id_evento LEFT JOIN LocalEsp l ON l.id_local=aa.id_local ORDER BY aa.data_acao DESC LIMIT 300")->fetchAll(PDO::FETCH_ASSOC);
$paginaAdmin='acoes'; $tituloAdmin='Histórico administrativo'; require __DIR__.'/includes/header.php';
?>
<section class="admin-panel admin-table-wrap"><div class="admin-panel-head"><div><p>AUDITORIA</p><h2>Últimas <?= count($acoes) ?> ações</h2></div></div><table class="admin-table"><thead><tr><th>Data</th><th>Administrador</th><th>Ação</th><th>Alvo</th><th>Motivo</th></tr></thead><tbody><?php if(!$acoes): ?><tr><td colspan="5" class="admin-vazio">Nenhuma ação registrada.</td></tr><?php endif; ?><?php foreach($acoes as $a): ?><tr><td><?= date('d/m/Y H:i',strtotime($a['data_acao'])) ?></td><td><?= htmlspecialchars($a['nome_adm']) ?></td><td><strong><?= htmlspecialchars($a['tipo_acao']) ?></strong></td><td><?php if($a['nome_user']): ?>Usuário: <?= htmlspecialchars($a['nome_user']) ?><?php elseif($a['nome_evento']): ?>Evento: <?= htmlspecialchars($a['nome_evento']) ?><?php elseif($a['nome_local']): ?>Local: <?= htmlspecialchars($a['nome_local']) ?><?php elseif($a['id_denuncia']): ?>Denúncia #<?= (int)$a['id_denuncia'] ?><?php else: ?>—<?php endif; ?></td><td><?= htmlspecialchars($a['motivo']) ?></td></tr><?php endforeach; ?></tbody></table></section>
<?php require __DIR__.'/includes/footer.php'; ?>
